package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.config.*;
import com.lianxibu.site.domain.protocol.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;

/** Four native original category closures including three verified zero cohorts; no synthetic empty components. */
class CatalogDayReportAggregateTest {
    boolean mysql(){return false;}
    CatalogDayReportProofNativeTest helper(){return new CatalogDayReportProofNativeTest(){@Override boolean mysql(){return CatalogDayReportAggregateTest.this.mysql();}};}
    record Built(CatalogAnalysisReportCandidateTest.Native nativeData,CatalogDayReportProofConfiguration.Components components,CatalogDayReportAggregateService service){ }
    Built fixture(String category,boolean closeZeros){var f=helper().helper().nativeCompletion(category,false);var original=f.fixture().built().data().data().data().data();var sourceFixture=original.f();var graphs=new LinkedHashMap<String,CatalogDayAnalysisProofGraph>();for(String value:CatalogSourceProofConfiguration.CATEGORIES){var source=value.equals(category)?sourceFixture.graph:new CatalogSourceProofGraph(f.fixture().f().source,f.fixture().f().tx,f.fixture().clock(),()->new FrozenGenerationSettings(7,List.of("fictional"),List.of()),()->true,value);var graph=new CatalogDayAnalysisProofGraph(f.fixture().f().source,f.fixture().f().tx,f.fixture().clock(),sourceFixture.cohorts,sourceFixture.runs,source,()->new FrozenGenerationSettings(7,List.of("fictional"),List.of()),()->true,value);graphs.put(value,graph);if(closeZeros)assertNotNull(graph.barrier().close(f.fixture().day()));}var components=CatalogDayReportProofConfiguration.assemble(f.fixture().f().source,f.fixture().f().tx,f.fixture().clock(),new CatalogDayAnalysisProofConfiguration.Graphs(graphs));return new Built(f,components,new CatalogDayReportAggregateService(components.byCategory(),f.fixture().f().tx));}
    <T>T read(Built f,java.util.function.Supplier<T> work){var tx=new TransactionTemplate(f.nativeData().fixture().f().tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->work.get());}
    @Test void FourActualOriginalClosuresShareOneNativeDirectoryAndKeepTheOneCompleteEntity(){for(String category:CatalogDayReportAggregateService.CATEGORIES){var f=fixture(category,true);var captured=f.service().capture(f.nativeData().fixture().day(),f.nativeData().cutoff());assertNotNull(captured);assertEquals(Set.copyOf(CatalogDayReportAggregateService.CATEGORIES),captured.components().keySet());assertEquals(1,captured.candidates().size());assertEquals(f.nativeData().completed().bodyJson(),captured.candidates().getFirst().evidence().bodyJson());assertEquals(1,captured.dependencies().size());assertEquals(1,captured.references().size());assertEquals(captured.candidates().getFirst().evidence().id(),captured.references().getFirst().evidenceId());assertEquals(f.nativeData().completed().version(),ContentVersionKey.fromJson(CanonicalJson.parse(captured.references().getFirst().targetJson())));assertTrue(captured.missing().isEmpty());for(var component:captured.components().values())assertEquals(captured.directory(),component.directory());assertFalse(captured.directory().sealedAt().isAfter(captured.cutoff()));assertSame(captured,read(f,()->f.service().verifyObserved(captured)));assertThrows(UnsupportedOperationException.class,()->captured.components().clear());assertThrows(UnsupportedOperationException.class,()->captured.references().clear());assertEquals(2,f.nativeData().fixture().f().sends);}}
    @Test void MissingOneOriginalCategoryCannotBeReplacedByAnInventedEmptyUniverse(){var f=fixture("agent",false);assertNull(f.service().capture(f.nativeData().fixture().day(),f.nativeData().cutoff()));assertEquals(2,f.nativeData().fixture().f().sends);}
    @Test void CurrentBlockAfterCaptureRejectsOldEligibilityAndNewAggregateKeepsOriginalExcludedBody(){var f=fixture("model",true);var captured=f.service().capture(f.nativeData().fixture().day(),f.nativeData().cutoff());f.nativeData().fixture().f().jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",f.nativeData().completed().version().contentId());read(f,()->{assertThrows(RuntimeException.class,()->f.service().verifyObserved(captured));return null;});var fresh=f.service().capture(f.nativeData().fixture().day(),f.nativeData().cutoff());assertTrue(fresh.candidates().getFirst().evidence().blocked());assertEquals(captured.candidates().getFirst().evidence().bodyJson(),fresh.candidates().getFirst().evidence().bodyJson());assertEquals(2,f.nativeData().fixture().f().sends);}
    @Test void MandatoryFourRoutesColdConstructionForeignIssuerAndTransactionsReject(){var tx=mock(PlatformTransactionManager.class);var map=new LinkedHashMap<String,CatalogDayReportComponentService>();for(String category:CatalogDayReportAggregateService.CATEGORIES){var service=mock(CatalogDayReportComponentService.class);when(service.category()).thenReturn(category);map.put(category,service);}new CatalogDayReportAggregateService(map,tx);verifyNoInteractions(tx);var missing=new LinkedHashMap<>(map);missing.remove("model");assertThrows(RuntimeException.class,()->new CatalogDayReportAggregateService(missing,tx));var wrong=new LinkedHashMap<>(map);wrong.put("model",map.get("agent"));assertThrows(RuntimeException.class,()->new CatalogDayReportAggregateService(wrong,tx));var f=fixture("skill",true);var captured=f.service().capture(f.nativeData().fixture().day(),f.nativeData().cutoff());assertThrows(RuntimeException.class,()->f.service().verifyObserved(captured));read(f,()->{assertThrows(RuntimeException.class,()->new CatalogDayReportAggregateService(f.components().byCategory(),f.nativeData().fixture().f().tx).verifyObserved(captured));return null;});var writer=new TransactionTemplate(f.nativeData().fixture().f().tx);writer.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);writer.execute(s->{assertThrows(RuntimeException.class,()->f.service().capture(f.nativeData().fixture().day(),f.nativeData().cutoff()));assertThrows(RuntimeException.class,()->f.service().verifyObserved(captured));return null;});}
    @Test void CombinedBudgetRetainsFullNativeOriginalInputsAndRejectsInsteadOfTruncatingCategories(){var f=fixture("agent",true);var value=f.service().capture(f.nativeData().fixture().day(),f.nativeData().cutoff());assertNotNull(value);assertTrue(value.originalByteSize()>f.nativeData().completed().bodyJson().getBytes(java.nio.charset.StandardCharsets.UTF_8).length);assertEquals(value.components().values().stream().mapToLong(CatalogDayReportComponentService.Captured::originalByteSize).sum(),value.originalByteSize());for(var component:value.components().values())assertTrue(component.originalByteSize()>0);var small=new CatalogDayReportAggregateService(f.components().byCategory(),f.nativeData().fixture().f().tx,1024);assertThrows(GenerationFlowService.CapacityGuarded.class,()->small.capture(f.nativeData().fixture().day(),f.nativeData().cutoff()));assertSame(value,read(f,()->f.service().verifyObserved(value)));assertThrows(RuntimeException.class,()->new CatalogDayReportAggregateService(f.components().byCategory(),f.nativeData().fixture().f().tx,1023));}
}
